/** Runs one attempt step by step. Returns early (leaving the job queued) if the worker is stopping. */
async function process(job: ClaimedJob): Promise<void> {
  for (let i = 1; i <= job.steps; i++) {
    if (stopping) {
      // Give the attempt back so that the restarted worker runs it again from the beginning.
      db.prepare(
        "UPDATE jobs SET status = 'queued', attempts = attempts - 1, progress_completed = 0, updated_at = ? WHERE id = ? AND status = 'running'",
      ).run(new Date().toISOString(), job.id);
      return;
    }
    await sleep(STEP_MS);
    db.prepare("UPDATE jobs SET progress_completed = ?, updated_at = ? WHERE id = ? AND status = 'running'").run(
      i,
      new Date().toISOString(),
      job.id,
    );
  }
  db.prepare(
    "UPDATE jobs SET status = 'completed', output = ?, progress_completed = steps, updated_at = ? WHERE id = ? AND status = 'running'",
  ).run(job.input.toUpperCase(), new Date().toISOString(), job.id);
}

async function main(): Promise<void> {
  // Jobs left running by a worker that died are processed again.
  db.prepare("UPDATE jobs SET status = 'queued', progress_completed = 0, updated_at = ? WHERE status = 'running'").run(
    new Date().toISOString(),
  );
  heartbeat();
  const beats = every(1000);
  const beating = (async () => {
    for await (const _ of beats) {
      if (stopping) break;
      heartbeat();
    }
  })();

  console.log('worker started');
  while (!stopping) {
    const job = claimNext();
    if (job) await process(job);
    else await sleep(100);
  }
  beats.return(undefined);
  await beating;
  db.close();
  console.log('worker stopped');
}

main().catch((e: unknown) => {
  console.error('worker failed:', e);
  process.exit(1);
});

